namespace Sunplus.Accounting.Business.SpecialDelete
{
    public class UpdateBatchMsg : IUpdateBatchMsg
    {
        private ISpecialDeleteDAO _specialDeleteDao;

        public UpdateBatchMsg()
            : this(null)
        {
        }

        public UpdateBatchMsg(ISpecialDeleteDAO specialDeleteDao)
        {
            _specialDeleteDao = specialDeleteDao ?? new SpecialDeleteDAO();
        }

        public Dictionary<string, string> UploadMsg(Message pmsg, string TransIds)
        {
            Dictionary<string, string> resultDto = new Dictionary<string, string>();

            if (!Permissions.GetHostPermission(Enumerations.Functions.SpecialDelete.SpecialDeleteSportBook))
            {
                resultDto.Add("500", ResourceExtension.GetResourceValue(ResourceExtension.Resources.ErrorMsg, "_500"));
            }
            try
            {
                #region send private message to users

                TransIds = TransIds.Replace("\n", string.Empty);

                var transIdDistinct = TransIds.Split(',').Select(s => s).Distinct().ToList();
                string str = string.Empty;
                //int cnt = 0;
                //foreach (string id in transIdDistinct)
                //{
                //    str += id + (cnt < transIdDistinct.Count - 1 ? ", " : string.Empty);
                //}
                TransIds = String.Join(",", transIdDistinct);

                var batches = GetTransIdsByBatch(TransIds);
                List<string> listTransIdDone = new List<string>();
                foreach (var batch in batches)
                {
                    SendPrivateMessageToUsers(pmsg, batch, ref listTransIdDone);
                }

                List<string> listTransIdFail = new List<string>();

                listTransIdFail = TransIds.Replace(" ", "").Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Except(listTransIdDone).ToList();

                string strTransIdDone = string.Empty;
                string strTransIdFail = string.Empty;

                var idsDone = listTransIdDone.Select(s => s).Distinct().ToList();

                strTransIdDone = String.Join(",", idsDone);
                strTransIdFail = String.Join(",", listTransIdFail);

                #endregion send private message to users

                if (strTransIdDone.Length > 0)
                {
                    resultDto.Add("-100", "Update Batch Msg successfully with TransId: " + strTransIdDone + ".");
                }
                if (strTransIdFail.Length > 0)
                {
                    resultDto.Add("100", "Update Batch Msg unsuccessfully with TransId: " + strTransIdFail + ".");
                }
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
            }
            return resultDto;
        }

        private List<string> GetTransIdsByBatch(string transIds)
        {
            List<string> batches = new List<string>();
            try
            {
                int transIdPerBatch = WebSettings.MaxTransIdPerBatch;
                int num = 0;
                string[] arrTransids = transIds.Split(',');
                num = arrTransids.Length / transIdPerBatch;
                if (arrTransids.Length % transIdPerBatch > 0)
                    num++;

                for (int i = 0; i < num; i++)
                {
                    var transidsPerBatch = arrTransids.Select(s => s).Skip(transIdPerBatch * (i)).Take(transIdPerBatch).ToList();
                    string batch = string.Empty;
                    foreach (string transId in transidsPerBatch)
                    {
                        try
                        {
                            batch += CastAide.AsInt64(transId) + ",";
                        }
                        catch (Exception ex)
                        {
                        }
                    }
                    batches.Add(batch);
                }
            }
            catch
            {
            }

            return batches;
        }

        private bool SendPrivateMessageToUsers(Message pmsg, string TransIds, ref List<string> listTransIdDone)
        {
            bool IsSuccess = false;
            try
            {
                DataTable dtMsg = _specialDeleteDao.SelBetBatchMsg(TransIds);

                if (dtMsg.Rows.Count > 0)
                {
                    var list = new Hashtable();
                    for (int i = 0; i < dtMsg.Rows.Count; i++)
                    {
                        string[] ArrColumnsNameDownLineID = { "custid", "recommend", "mrecommend", "srecommend" };
                        string[] ArrColumnsNameDownLineUserName = {
                                                                        "CustUserName", "AgUserName", "MagUserName",
                                                                        "SagUserName"
                                                                    };

                        for (int j = 0; j < ArrColumnsNameDownLineID.Length; j++)
                        {
                            string cnameID = ArrColumnsNameDownLineID[j];
                            string cnameUser = ArrColumnsNameDownLineUserName[j];

                            string custid = dtMsg.Rows[i][cnameID].ToString();
                            string uname = dtMsg.Rows[i][cnameUser].ToString();

                            string key = custid + "^" + uname;
                            string ticknum = dtMsg.Rows[i]["transid"].ToString();

                            if (list[key] != null)
                            {
                                if (list[key].ToString().IndexOf(ticknum) == -1)
                                {
                                    string _tmp = list[key].ToString();
                                    list.Remove(key);
                                    list.Add(key, _tmp + "," + ticknum);
                                }
                            }
                            else
                                list.Add(key, ticknum);
                        }
                    }

                    var dtDeletedBet = new DataTable();
                    dtDeletedBet.Columns.Add("custid", typeof(int));
                    dtDeletedBet.Columns.Add("username", typeof(string));
                    dtDeletedBet.Columns.Add("transids", typeof(string));
                    dtDeletedBet.Columns.Add("betcount", typeof(int));

                    foreach (DictionaryEntry Key in list)
                    {
                        int custid = CastAide.AsInt32(Key.Key.ToString().Split('^')[0]);
                        // This is a CustID of ticket that is deleted [TargetID Field]
                        string uname = Key.Key.ToString().Split('^')[1];
                        //This is a UserName of ticket that is deleted [TargetName Field]
                        DataRow dr = dtDeletedBet.NewRow();
                        dr["custid"] = custid;
                        dr["username"] = uname;
                        string[] ArrTransids = Key.Value.ToString().Split(',');
                        Array.Sort(ArrTransids);
                        string strTransIDs = "";
                        for (int i = 0; i < ArrTransids.Length; i++)
                        {
                            strTransIDs += ArrTransids[i] + ", ";
                        }
                        strTransIDs = strTransIDs.Substring(0, strTransIDs.Length - 2);
                        dr["transids"] = strTransIDs;
                        dr["betcount"] = Key.Value.ToString().Split(',').Length;
                        dtDeletedBet.Rows.Add(dr);
                    }
                    DataView dv = dtDeletedBet.DefaultView;
                    dv.Sort = "betcount asc, transids asc";
                    DataTable dtBets = dv.ToTable();

                    pmsg.CreatorId = Convert.ToInt32(AppSession.AccId);
                    pmsg.CreatorName = AppSession.AccUserName;

                    // send private message to users for cancel their transactions
                    int MessageId = 0;
                    int matchId = 0;
                    foreach (DataRow dr in dtBets.Rows)
                    {
                        int[] custid = { CastAide.AsInt32(dr["custid"]) };
                        // This is a CustID of ticket that is deleted [TargetID Field]
                        string[] uname = { CastAide.AsString(dr["username"]) };
                        //This is a UserName of ticket that is deleted [TargetName Field]
                        if (CastAide.AsInt32(dr["custid"]) < 100) continue; //SRecommend < 100 and roleid=3
                        string[] bettransid = { CastAide.AsString(dr["transids"]) };

                        if (MessageId == 0)
                            MessageId = Messenger.SetMessage(pmsg, custid, uname, matchId, bettransid);
                        else
                            Messenger.AddTargt2Message(MessageId, custid, uname, bettransid);

                        foreach (string transid in CastAide.AsString(dr["transids"]).Split(','))
                        {
                            listTransIdDone.Add(transid.Trim());
                        }

                        IsSuccess = true;
                    }
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return IsSuccess;
        }
    }
}